import { Feather, Ionicons, MaterialCommunityIcons } from "@expo/vector-icons";
import * as React from 'react';

export type SemanticIconProps = {
  size?: number;
  color?: string;
  className?: string;
  strokeWidth?: number;
  weight?: 'thin' | 'light' | 'regular' | 'bold' | 'fill' | 'duotone';
  accessibilityLabel?: string;
  decorative?: boolean;
  [key: string]: unknown;
};
export type SemanticIconComponent = React.ComponentType<SemanticIconProps>;

function createExpoSemanticIcon(IconSet: React.ComponentType<any>, name: string, displayName: string): SemanticIconComponent {
  const Component = React.forwardRef<any, SemanticIconProps>(function SemanticIcon(
    {
      size = 16,
      color = 'currentColor',
      className,
      accessibilityLabel,
      decorative = !accessibilityLabel,
      ...props
    },
    ref
  ) {
    return <IconSet ref={ref} name={name as any} size={size} color={color} className={className} accessibilityLabel={decorative ? undefined : accessibilityLabel} aria-hidden={decorative} {...props} />;
  });
  Component.displayName = displayName;
  return Component;
}

